typedef int SSEventId;
class entity;

enum EventType {
    SS_FE_ONX = 24
};

class SoundScriptManager {
public:
    static SoundScriptManager *instance;
    static inline SoundScriptManager *inst() { return instance; }
    void pause();
    void unpause();
    SSEventId playEvent(
        EventType type,
        entity *e = 0,
        float fadeInTime = 0);
};

struct FEManager {
    char padding[0x15678];
    bool fe_done;
};

extern FEManager frontendmanager;

struct FEMenuEntry {
    int entry_num;
};

class SaveLoadFrontEnd {
public:
    void DialogNoPressed();
    void DialogYesOKPressed();
};

class DialogMenu {
public:
    enum {
        DM_TYPE_MNG,
        DM_TYPE_FMT,
        DM_TYPE_YES,
        DM_TYPE_OK,
        DM_TYPE_PROGRESS,
        DM_TYPE_EMPTY
    };

private:
    enum {
        DM_YES,
        DM_NO,
        DM_OK,
        DM_FMT,
        DM_CNL,
        DM_MNG,
        DM_CNL2,
        DM_NUM
    };

    char padding0[0x4c];
    FEMenuEntry *highlighted;
    char padding1[0x64 - 0x50];
    SaveLoadFrontEnd *parent;
    char padding2[0x168 - 0x68];
    int type;

public:
    void OnCross(int c);
};

